def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x, lb, ub):
        return np.clip(x, lb, ub)

    x = rng.uniform(lb, ub, size=dim)
    best_x = x.copy()
    best_f = func(x)

    def de_step(pop_size, f):
        nonlocal best_x
        children = []
        for _ in range(pop_size):
            idx1, idx2, idx3 = rng.choice(dim, 3, replace=False)
            offspring = x.copy()
            step_size = rng.uniform(0.01, 0.5)
            offspring[idx1], offspring[idx2] = clip(offspring[idx1] + step_size * (x[idx2] - x[idx1]), lb, ub), \
                                              clip(offspring[idx2] + step_size * (x[idx3] - x[idx2]))
            children.append(f(offspring))
        if any(np.array(children) < best_f):
            idx = np.argmin(np.array(children))
            x = np.clip(x + 0.1 * np.array([x[i] - best_x[i] for i in range(dim)]), lb, ub)
            x[idx] = children[idx]

    def sa_step(t):
        nonlocal best_x
        step_size = rng.uniform(0.01, 0.5)
        x_new = clip(x + step_size * np.random.normal(size=dim), lb, ub)
        if func(x_new) < func(x):
            x = x_new

    for _ in range(budget):
        de_step(50, func)
        sa_step(_ / budget)

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    def grad(x):
        return 2 * (x[1:] - x[:-1]**2)[:, None] * 200 * (x[1:] - x[:-1]**2) + 2 * (x[:-1] - 1)

    x = np.array([rng.uniform(lb, ub) for _ in range(dim)])
    best_x = x.copy()
    best_fx = func(x)

    for _ in range(budget):
        step_size = rng.uniform(0.01, 0.1)
        direction = rng.choice([-1, 1], size=dim)

        new_x = x + step_size * direction
        new_x = np.clip(new_x, lb, ub)

        new_fx = func(new_x)

        if new_fx < best_fx:
            best_fx = new_fx
            best_x = new_x.copy()

        grad_value = grad(x)
        if rng.uniform(0, 1) > 0.5:
            x += step_size * grad_value
        else:
            x += np.sign(grad_value) * step_size

        x = np.clip(x, lb, ub)

    return best_x

